head.script:
// 테스트 설명, 유효성 값 설정
//  - _1 : 표시 방향과 컴포넌트 주변 공간 (auto / 미설정 / down / up)
//  - _2 : up 일 때의 slideDown 애니메이션 (down 대조)
//  - _3 : fit 과 아이템 정의 방식
scwin.tData = {
    "description" : "[autoComplete > P > direction]<br/>AutoComplete 컴포넌트의 아이템 리스트창이 표시되는 방향을 설정합니다.",
    "validation" : [
        "up 설정 시, animation='slideDown' 인 경우 애니메이션 효과가 적용되지 않습니다.",
    ]
}



// 확인 버튼을 누르는 순간의 리스트창 상태 (버튼 클릭으로 리스트창이 닫히기 전에 기록)
scwin.gVar = { "snap" : null };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_direction.setValue("up");
    con_animation.setValue("slideDown");

    // 확인 버튼 클릭 시 리스트창이 닫히므로, 닫히기 전(mousedown)에 리스트창 상태를 기록
    btn_getAnimation.render.addEventListener("mousedown", scwin.captureListState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    scwin.gVar.snap = null;

    $c.gcm.createLabel('label="[절차] 화살표 버튼 클릭으로 리스트창 열기 -> 리스트창이 열린 상태에서 확인 버튼"', '', 'label1');

    // 미설정 옵션은 속성 자체를 넣지 않는다 (createCList 가 빈값 키 제외)
    let properties = {
        direction : con_direction.getValue(),
        animation : con_animation.getValue()
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicAutoComplete(cList);
};



// 확인 버튼을 누르는 순간의 리스트창 상태 기록
scwin.captureListState = function (e) {
    scwin.gVar.snap = null;
    if (typeof target1 === 'undefined') {
        return;
    }
    let listElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    if (!listElem) {
        return;
    }
    let objStyle = getComputedStyle(listElem);
    if (objStyle.display === "none" || objStyle.visibility === "hidden") {
        return;
    }

    let rectList = listElem.getBoundingClientRect();
    let rectComp = target1.render.getBoundingClientRect();

    scwin.gVar.snap = {
        "direction" : (rectList.top < rectComp.top) ? "컴포넌트 상단" : "컴포넌트 하단",
        "className" : listElem.className
    };
};



// 리스트창 표시 방향과 slideDown 애니메이션 클래스 적용 여부 출력 (validation 1)
scwin.btn_getAnimation_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let snap = scwin.gVar.snap;
    if (!snap) {
        bottom.setReturnValue("리스트창 열림 : false");
        return;
    }

    let bSlideDown = snap.className.split(/\s+/).indexOf("w2slideDown") > -1;
    let strAnimation = con_animation.getValue() === "" ? "미설정" : con_animation.getValue();

    bottom.setReturnValue("direction : " + con_direction.getValue() + " / animation : " + strAnimation + " -> 리스트창 표시 방향 : " + snap.direction + " / 리스트창 애니메이션 클래스 : " + (bSlideDown ? "w2slideDown" : "없음"));
};
